// MuxMan is Mux_Man_t.
type MuxMan struct {
	pGia   *GiaManager      // manager
	pNames *StringNameTable // Abc_Nam_t * : hashing name into ID
	vTops  *IntLevelVector  // top nodes for each struct
}

// GiaObjType is Gia_ObjType_t, generated by GIA_FOREACH_ITEM; the C enumerators
// are the bare names C0, PO, PI, ... and appear here with a GiaObjType prefix.
type GiaObjType int

const (
	GiaObjTypeC0 GiaObjType = iota
	GiaObjTypePO
	GiaObjTypePI
	GiaObjTypeFF
	GiaObjTypeXOR
	GiaObjTypeMUX
	GiaObjTypeAND
	GiaObjTypeiC0
	GiaObjTypeiC1
	GiaObjTypeiPI
	GiaObjTypeiFF
	GiaObjTypeiXOR
	GiaObjTypeiMUX
	GiaObjTypeiAND
	GiaObjTypeiANDn
	GiaObjTypeiANDp
	GiaObjTypeoPO
	GiaObjTypeoFF
	GiaObjTypeoXOR
	GiaObjTypeoMUXc
	GiaObjTypeoMUXd
	GiaObjTypeoAND
	GiaObjTypeoANDn
	GiaObjTypeoANDp
	GIA_END
)

